document.querySelectorAll('[data-ce-editor-doc]').forEach(function (f) {
  var titulo = f.querySelector('[data-titulo]'), vivo = f.querySelector('[data-titulo-vivo]');
  titulo.addEventListener('input', function () { vivo.textContent = titulo.value.trim() || 'Nueva noticia'; });
  f.querySelectorAll('[data-contar]').forEach(function (campo) {
    var c = document.createElement('span'); c.className = 'ce-editor-doc__contador';
    campo.insertAdjacentElement('afterend', c);
    var min = +campo.dataset.min, max = +campo.dataset.max;
    function pintar() { var n = campo.value.length; c.textContent = n + ' / ' + max; c.classList.toggle('ce-editor-doc__contador--mal', n > max || (n > 0 && n < min)); }
    campo.addEventListener('input', pintar); pintar();
  });
  var pestanas = f.querySelectorAll('.ce-editor-doc__pestana');
  pestanas.forEach(function (p) { p.addEventListener('click', function () { pestanas.forEach(function (o) { o.setAttribute('aria-selected', String(o === p)); }); }); });
});

