document.querySelectorAll('[data-ce-foto]').forEach(function (zona) {
  var input = zona.querySelector('input'), img = zona.querySelector('img'), vacia = zona.querySelector('.ce-zona-foto__vacia'), cambiar = zona.querySelector('.ce-zona-foto__cambiar');
  function mostrar(archivo) {
    if (!archivo) return;
    img.src = URL.createObjectURL(archivo); img.hidden = false; vacia.hidden = true; cambiar.textContent = 'Cambiar foto';
  }
  input.addEventListener('change', function () { mostrar(input.files[0]); });
  zona.addEventListener('dragover', function (e) { e.preventDefault(); zona.classList.add('is-encima'); });
  zona.addEventListener('dragleave', function () { zona.classList.remove('is-encima'); });
  zona.addEventListener('drop', function (e) { e.preventDefault(); zona.classList.remove('is-encima'); mostrar(e.dataTransfer.files[0]); });
});

