document.querySelectorAll('[data-ce-editor]').forEach(function (ed) {
  var area = ed.querySelector('.ce-editor-texto__area'), estado = ed.querySelector('[data-apartados]');
  function contar() { var n = area.querySelectorAll('h2').length; estado.textContent = n + (n === 1 ? ' apartado' : ' apartados') + ' en el índice' + (n < 2 ? ' · añade al menos 2 «Título» para que salga el índice' : ''); estado.classList.toggle('is-mal', n < 2); }
  ed.querySelectorAll('[data-orden]').forEach(function (b) {
    b.addEventListener('mousedown', function (e) { e.preventDefault(); });
    b.addEventListener('click', function () { document.execCommand(b.dataset.orden, false, b.dataset.valor ? '<' + b.dataset.valor + '>' : null); contar(); });
  });
  area.addEventListener('paste', function (e) { e.preventDefault(); document.execCommand('insertText', false, e.clipboardData.getData('text/plain')); });
  area.addEventListener('input', contar); contar();
});

