@property --ce-progreso{syntax:'<number>';inherits:true;initial-value:0}
.ce-boton-estados-demo{display:flex;flex-wrap:wrap;gap:1rem;align-items:center;padding:1.5rem;font-family:'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;background:#fff}
.ce-boton-estados{--alto:3.375rem;position:relative;display:inline-flex;align-items:center;gap:.625rem;min-height:var(--alto);padding:0 .25rem 0 1.375rem;border:2px solid transparent;border-radius:999px;background:#2929fd;color:#fff;font:600 1rem/1.15 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;cursor:pointer;transition:background-color 150ms cubic-bezier(.4,0,.2,1),transform 150ms}
.ce-boton-estados:hover{background:#2023ce}
.ce-boton-estados:active:not([data-estado='procesando']){transform:scale(.97)}
.ce-boton-estados[data-estado='procesando']{cursor:progress;pointer-events:none}
.ce-boton-estados__textos{display:inline-grid;overflow:clip}
.ce-boton-estados__texto{grid-area:1/1;text-align:center;translate:0 100%;opacity:0;transition:translate 300ms cubic-bezier(.16,1,.3,1),opacity 300ms cubic-bezier(.16,1,.3,1)}
[data-estado='normal'] > .ce-boton-estados__textos [data-para='normal'],[data-estado='procesando'] > .ce-boton-estados__textos [data-para='procesando'],[data-estado='hecho'] > .ce-boton-estados__textos [data-para='hecho'],[data-estado='error'] > .ce-boton-estados__textos [data-para='error']{translate:0 0;opacity:1}
[data-estado='procesando'] > .ce-boton-estados__textos [data-para='normal'],[data-estado='hecho'] > .ce-boton-estados__textos :is([data-para='normal'],[data-para='procesando']),[data-estado='error'] > .ce-boton-estados__textos :is([data-para='normal'],[data-para='procesando']){translate:0 -100%}
.ce-boton-estados__indicador{position:relative;display:grid;place-items:center;flex-shrink:0;width:calc(var(--alto) - 2 * (.25rem + 2px));aspect-ratio:1;border-radius:999px;overflow:clip;background:color-mix(in srgb,currentColor 16%,transparent);isolation:isolate;transition:background 150ms}
.ce-boton-estados__indicador > *{grid-area:1/1}
.ce-boton-estados__indicador svg{width:1.125rem;height:1.125rem}
.ce-boton-estados__liquido{position:absolute;left:-50%;top:0;z-index:-1;width:200%;aspect-ratio:1;border-radius:40%;background:currentColor;translate:0 calc(50% - var(--ce-progreso) * 57.5%);opacity:0;animation:ce-boton-ola 2.4s linear infinite;transition:--ce-progreso 3s cubic-bezier(.4,0,.2,1),opacity 150ms cubic-bezier(.4,0,.2,1)}
[data-estado='procesando'] .ce-boton-estados__liquido,[data-estado='hecho'] .ce-boton-estados__liquido{opacity:1}
.ce-boton-estados[data-estado='procesando']{--ce-progreso:.7}
.ce-boton-estados[data-estado='hecho']{--ce-progreso:1}
[data-estado='hecho'] .ce-boton-estados__liquido{transition-duration:300ms,150ms}
[data-estado='error'] .ce-boton-estados__liquido,[data-estado='normal'] .ce-boton-estados__liquido{transition:--ce-progreso 150ms linear 150ms,opacity 150ms cubic-bezier(.4,0,.2,1)}
[data-estado='error'] .ce-boton-estados__indicador{background:#b42318}
@keyframes ce-boton-ola{to{rotate:1turn}}
.ce-boton-estados__icono-inicial{transition:translate 300ms cubic-bezier(.16,1,.3,1),scale 300ms cubic-bezier(.16,1,.3,1),opacity 150ms}
.ce-boton-estados:not([data-estado='normal']) .ce-boton-estados__icono-inicial{translate:0 -.5rem;scale:.3;opacity:0}
.ce-boton-estados__icono-hecho{color:#2929fd}
.ce-boton-estados__icono-hecho path{stroke-dasharray:24;stroke-dashoffset:24;transition:stroke-dashoffset 300ms cubic-bezier(.16,1,.3,1)}
[data-estado='hecho'] .ce-boton-estados__icono-hecho path{stroke-dashoffset:0;transition-delay:300ms}
.ce-boton-estados__icono-error{color:#fff;scale:.3;opacity:0;transition:scale 300ms cubic-bezier(.16,1,.3,1),opacity 150ms}
[data-estado='error'] .ce-boton-estados__icono-error{scale:1;opacity:1}
.ce-boton-estados[data-estado='error']{animation:ce-boton-sacudir 300ms cubic-bezier(.4,0,.2,1)}
@keyframes ce-boton-sacudir{25%{translate:-.25rem 0}75%{translate:.25rem 0}}
.ce-boton-estados-flair{position:relative;isolation:isolate;display:inline-flex;align-items:center;gap:.625rem;min-height:3.375rem;padding:0 1.25rem 0 1.375rem;border:2px solid #2929fd;border-radius:999px;color:#2929fd;font-weight:600;text-decoration:none;transition:color 150ms}
.ce-boton-estados-flair svg{width:1.125rem;height:1.125rem;transition:translate 300ms cubic-bezier(.16,1,.3,1)}
.ce-boton-estados-flair:hover svg{translate:.25rem 0}
.ce-boton-estados-flair.is-lleno{color:#fff}
.ce-boton-estados-flair__relleno{position:absolute;inset:-2px;z-index:-1;overflow:hidden;border-radius:inherit;pointer-events:none}
.ce-boton-estados-flair__circulo{position:absolute;top:0;left:0;width:100%;height:100%;translate:var(--x,50%) var(--y,50%);scale:var(--s,0);transform-origin:0 0;transition:translate 600ms cubic-bezier(.16,1,.3,1),scale 600ms cubic-bezier(.16,1,.3,1)}
.ce-boton-estados-flair__circulo::before{content:'';position:absolute;top:0;left:0;width:230%;aspect-ratio:1;border-radius:999px;background:#2929fd;transform:translate(-50%,-50%)}
@media (prefers-reduced-motion:reduce){.ce-boton-estados-flair:hover svg{translate:none}}

