document.querySelectorAll('[data-ce-estados]').forEach(function (b) {
  b.addEventListener('click', function () {
    b.dataset.estado = 'procesando';
    setTimeout(function () {
      b.dataset.estado = b.dataset.ceEstados;
      setTimeout(function () { b.dataset.estado = 'normal'; }, 2200);
    }, 1800);
  });
});
document.querySelectorAll('[data-ce-flair]').forEach(function (b) {
  var c = b.querySelector('.ce-boton-estados-flair__circulo');
  function pos(e) { var r = b.getBoundingClientRect(); c.style.setProperty('--x', ((e.clientX - r.left) / r.width * 100) + '%'); c.style.setProperty('--y', ((e.clientY - r.top) / r.height * 100) + '%'); }
  b.addEventListener('pointerenter', function (e) { c.style.transition = 'none'; pos(e); c.offsetWidth; c.style.transition = ''; c.style.setProperty('--s', 1); b.classList.add('is-lleno'); });
  b.addEventListener('pointermove', pos);
  b.addEventListener('pointerleave', function (e) { pos(e); c.style.setProperty('--s', 0); b.classList.remove('is-lleno'); });
});

