document.querySelectorAll('[data-ce-grafico]').forEach(function (raiz) {
  var cfg = JSON.parse(raiz.dataset.ceGrafico), lienzo = raiz.querySelector('.ce-grafico__lienzo');
  var guia = raiz.querySelector('.ce-grafico__guia'), punto = raiz.querySelector('.ce-grafico__punto'), ficha = raiz.querySelector('.ce-grafico__ficha');
  var puntos = [], nombre = 'Visitantes';
  function redondo(n) { var p = Math.pow(10, Math.floor(Math.log10(n))); return Math.ceil(n / p) * p; }
  function pintar(clave, texto) {
    nombre = texto; raiz.querySelector('[data-nombre]').textContent = texto;
    var s = cfg.series[clave], max = redondo(Math.max.apply(null, s.v.concat(s.a))), n = s.v.length;
    function xy(v, i) { return [i / (n - 1) * 100, 100 - v / max * 100]; }
    puntos = s.v.map(function (v, i) { var p = xy(v, i); return { e: cfg.dias[i], v: v, a: s.a[i], x: p[0], y: p[1] }; });
    var linea = puntos.map(function (p, i) { return (i ? 'L' : 'M') + p.x + ' ' + p.y; }).join(' ');
    var ant = s.a.map(function (v, i) { var p = xy(v, i); return (i ? 'L' : 'M') + p[0] + ' ' + p[1]; }).join(' ');
    var paths = raiz.querySelectorAll('svg path');
    paths[0].setAttribute('d', linea + ' L100 100 L0 100 Z'); paths[1].setAttribute('d', ant); paths[2].setAttribute('d', linea);
    lienzo.querySelectorAll('.ce-grafico__rejilla').forEach(function (r) { r.remove(); });
    var ejeY = raiz.querySelector('.ce-grafico__eje-y'); ejeY.innerHTML = '';
    [0, .25, .5, .75, 1].forEach(function (f) {
      var t = (1 - f) * 100, sp = document.createElement('span'); sp.style.top = t + '%'; sp.textContent = Math.round(max * f).toLocaleString('es-ES'); ejeY.appendChild(sp);
      var r = document.createElement('span'); r.className = 'ce-grafico__rejilla'; r.style.top = t + '%'; lienzo.insertBefore(r, lienzo.firstChild);
    });
    var ejeX = raiz.querySelector('.ce-grafico__eje-x'); ejeX.innerHTML = '';
    [0, 4, 9, 13].forEach(function (i) { var sp = document.createElement('span'); sp.style.left = puntos[i].x + '%'; sp.textContent = puntos[i].e; ejeX.appendChild(sp); });
    ocultar();
  }
  function mostrar(i) {
    var d = puntos[i]; if (!d) return; actual = i;
    guia.hidden = punto.hidden = ficha.hidden = false;
    guia.style.left = punto.style.left = ficha.style.left = d.x + '%'; punto.style.top = d.y + '%';
    ficha.classList.toggle('ce-grafico__ficha--izquierda', d.x > 65);
    ficha.replaceChildren();
    var t = document.createElement('strong'); t.textContent = d.e;
    var v = document.createElement('span'); v.textContent = nombre + ': ' + d.v.toLocaleString('es-ES');
    var a = document.createElement('span'); a.className = 'ce-grafico__ficha-anterior'; a.textContent = 'Periodo anterior: ' + d.a.toLocaleString('es-ES');
    ficha.append(t, v, a);
  }
  function ocultar() { guia.hidden = punto.hidden = ficha.hidden = true; }
  var actual = -1;
  lienzo.addEventListener('pointermove', function (e) { var r = lienzo.getBoundingClientRect(); mostrar(Math.round((e.clientX - r.left) / r.width * (puntos.length - 1))); });
  lienzo.addEventListener('pointerleave', ocultar);
  lienzo.addEventListener('keydown', function (e) { if (e.key === 'ArrowRight') mostrar(Math.min(puntos.length - 1, actual + 1)); if (e.key === 'ArrowLeft') mostrar(Math.max(0, actual - 1)); });
  var botones = raiz.querySelectorAll('[data-serie]');
  botones.forEach(function (b) { b.addEventListener('click', function () { botones.forEach(function (o) { o.setAttribute('aria-selected', String(o === b)); }); pintar(b.dataset.serie, b.querySelector('.ce-grafico__nombre').textContent); }); });
  pintar('visitantes', 'Visitantes');
});

