.ce-lista-barras__texto{display:flex;align-items:baseline;gap:.5rem;min-width:0}
.ce-lista-barras__nombre{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color 150ms}
a.ce-lista-barras__fila:hover .ce-lista-barras__nombre{color:#2929fd}
.ce-lista-barras__valores{display:flex;flex-direction:column-reverse;align-items:flex-end;font-variant-numeric:tabular-nums}
