@media (prefers-reduced-motion:no-preference){.ce-en-vivo__latido::after{animation:ce-en-vivo-latido 2s cubic-bezier(.16,1,.3,1) infinite}}
@keyframes ce-en-vivo-latido{from{opacity:.8;transform:scale(1)}to{opacity:0;transform:scale(3)}}
