document.querySelectorAll('[data-ce-en-vivo]').forEach(function (b) {
  // Demo: en el panel real se pide /api/panel/estadisticas-en-vivo/ cada 10 s
  setInterval(function () {
    if (document.visibilityState !== 'visible') return;
    b.querySelector('[data-ahora]').textContent = String(4 + Math.floor(Math.random() * 6));
    b.querySelectorAll('.ce-en-vivo__minutos > span').forEach(function (s) { s.style.setProperty('--proporcion', Math.random().toFixed(3)); });
  }, 10000);
});

