document.querySelectorAll('[data-um-listado]').forEach(function (r) {
  var origen = (location.hash.match(/origen=(\w+)/) || [])[1] || 'todos', q = '';
  function filtrar() {
    r.querySelectorAll('.um-listado-tarjeta__chip').forEach(function (c) { c.classList.toggle('activo', c.dataset.origen === origen); });
    r.querySelectorAll('tbody tr').forEach(function (tr) { tr.hidden = !((origen === 'todos' || tr.dataset.origen === origen) && tr.textContent.toLowerCase().indexOf(q) > -1); });
  }
  r.querySelectorAll('.um-listado-tarjeta__chip').forEach(function (c) { c.addEventListener('click', function () { origen = c.dataset.origen; history.replaceState(null, '', '#origen=' + origen); filtrar(); }); });
  r.querySelector('[data-buscar]').addEventListener('input', function (e) { q = e.target.value.toLowerCase(); filtrar(); });
  filtrar();
});

