(function () {
  var ICONOS = { success: '<path d="M8 12.5l3 3 5-6"/>', error: '<path d="M9 9l6 6M15 9l-6 6"/>', warning: '<path d="M12 8v5M12 16v.5"/>', info: '<path d="M12 11v5M12 8v.5"/>' };
  var TEXTOS = { success: 'Cambios guardados', error: 'No se ha podido guardar', warning: 'Faltan datos del curso', info: 'El vídeo se está procesando' };
  function mostrarToast(cont, msg, tipo, ms) {
    var t = document.createElement('div'); t.className = 'um-toast um-toast--' + tipo; t.setAttribute('role', 'status'); t.setAttribute('aria-live', /error|warning/.test(tipo) ? 'assertive' : 'polite');
    t.innerHTML = '<svg class="um-toast__icono" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9.5"/>' + ICONOS[tipo] + '</svg><span class="um-toast__texto"></span><button type="button" class="um-toast__cerrar" aria-label="Cerrar">×</button>';
    t.querySelector('.um-toast__texto').textContent = msg; cont.appendChild(t);
    var resto = ms, inicio, temp;
    function cerrar() { t.classList.add('is-cerrando'); setTimeout(function () { t.remove(); }, 220); }
    function arrancar() { inicio = Date.now(); temp = setTimeout(cerrar, resto); }
    t.addEventListener('mouseenter', function () { clearTimeout(temp); resto -= Date.now() - inicio; });
    t.addEventListener('mouseleave', arrancar);
    t.querySelector('button').addEventListener('click', cerrar);
    if (ms > 0) arrancar();
  }
  document.querySelectorAll('.um-toast-demo').forEach(function (d) {
    var cont = d.querySelector('.um-toast-contenedor');
    d.querySelectorAll('[data-um-toast]').forEach(function (b) { b.addEventListener('click', function () { mostrarToast(cont, TEXTOS[b.dataset.umToast], b.dataset.umToast, 4000); }); });
  });
})();

