(function () {
  function abrir(o) {
    return new Promise(function (resolver) {
      var previo = document.activeElement, velo = document.createElement('div');
      velo.className = 'um-modal'; velo.setAttribute('role', 'dialog'); velo.setAttribute('aria-modal', 'true');
      var t = document.createElement('div'); t.className = 'um-modal__tarjeta'; velo.appendChild(t);
      if (o.titulo) { var h = document.createElement('h2'); h.className = 'um-modal__titulo'; h.id = 'um-modal-t'; h.textContent = o.titulo; t.appendChild(h); velo.setAttribute('aria-labelledby', 'um-modal-t'); }
      if (o.mensaje) { var p = document.createElement('p'); p.className = 'um-modal__mensaje'; p.textContent = o.mensaje; t.appendChild(p); }
      var inputs = (o.campos || []).map(function (c) { var d = document.createElement('div'); d.className = 'um-modal__campo'; var l = document.createElement('label'); l.textContent = c.etiqueta; var i = document.createElement('input'); i.value = c.valor || ''; i.type = c.tipo || 'text'; d.append(l, i); t.appendChild(d); return i; });
      var acc = document.createElement('div'); acc.className = 'um-modal__acciones';
      var no = document.createElement('button'); no.className = 'um-modal__btn um-modal__btn--cancelar'; no.textContent = o.textoCancelar || 'Cancelar';
      var si = document.createElement('button'); si.className = 'um-modal__btn um-modal__btn--confirmar' + (o.peligro ? ' um-modal__btn--peligro' : ''); si.textContent = o.textoConfirmar || 'Aceptar';
      acc.append(no, si); t.appendChild(acc); document.body.appendChild(velo);
      function cerrar(v) { velo.remove(); document.removeEventListener('keydown', teclas); if (previo) previo.focus(); resolver(v); }
      function ok() { cerrar(inputs.length ? inputs.map(function (i) { return i.value; }) : true); }
      function teclas(e) {
        if (e.key === 'Escape') cerrar(inputs.length ? null : false);
        if (e.key === 'Enter' && inputs.indexOf(e.target) > -1) ok();
        if (e.key === 'Tab') { var f = t.querySelectorAll('input,button'), pri = f[0], ult = f[f.length - 1]; if (e.shiftKey && document.activeElement === pri) { e.preventDefault(); ult.focus(); } else if (!e.shiftKey && document.activeElement === ult) { e.preventDefault(); pri.focus(); } }
      }
      document.addEventListener('keydown', teclas);
      no.onclick = function () { cerrar(inputs.length ? null : false); }; si.onclick = ok;
      velo.addEventListener('click', function (e) { if (e.target === velo) cerrar(inputs.length ? null : false); });
      (inputs[0] || si).focus();
    });
  }
  document.querySelectorAll('.um-modal-demo').forEach(function (d) {
    var out = d.querySelector('[data-um-resultado]');
    d.querySelector('[data-um-borrar]').onclick = function () { abrir({ titulo: 'Eliminar curso', mensaje: '¿Seguro? Se borrarán todos sus temas.', textoConfirmar: 'Eliminar', peligro: true }).then(function (v) { out.textContent = v ? 'Eliminado' : 'Cancelado'; }); };
    d.querySelector('[data-um-precio]').onclick = function () { abrir({ titulo: 'Precio del curso', campos: [{ etiqueta: 'Precio (€)', tipo: 'number', valor: '49.00' }], textoConfirmar: 'Guardar' }).then(function (v) { out.textContent = v ? 'Nuevo precio: ' + v[0] + ' €' : 'Cancelado'; }); };
  });
})();

