  r.querySelectorAll('[data-toggle]').forEach(function (f) { f.addEventListener('click', function () { f.parentElement.classList.toggle('abierto'); }); });
  var tabs = r.querySelectorAll('.um-tickets__tab');
  tabs.forEach(function (t) { t.addEventListener('click', function () { tabs.forEach(function (o) { o.classList.toggle('activo', o === t); }); }); });
});

piezas.css:
.um-temas{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box}
.um-tema{background:#fff;border:1px solid #e4ede9;border-radius:14px;margin-bottom:1rem;overflow:hidden;box-shadow:0 2px 10px rgba(0,0,0,.05)}
.um-tema.is-arrastrando{opacity:.4;box-shadow:none}
.um-temas__indicador{height:3px;background:#3aaa74;border-radius:2px;margin:-.5rem 0 .5rem}
.um-tema__cab{display:flex;align-items:center;gap:.75rem;padding:1rem 1.25rem;background:#fafcfb;border-bottom:1px solid #f0f4f2}
.um-tema__asa{color:#aab;cursor:grab;padding:.3rem .4rem;display:flex;border-radius:6px}
.um-tema__asa:hover{background:#eef2ef;color:#556}
.um-tema__num{width:28px;height:28px;border-radius:8px;background:#b3e8da;display:flex;align-items:center;justify-content:center;font-size:.7rem;font-weight:800;flex-shrink:0}
.um-tema__titulos{flex:1;display:flex;flex-direction:column;gap:.15rem;min-width:0}
.um-tema__titulo{font-size:.88rem;font-weight:700}
.um-tema__desc{font-size:.75rem;color:#8aa09a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.um-tema__dur{font-size:.7rem;padding:.18rem .65rem;border-radius:20px;background:#f0f4f2;color:#6a8a7d;font-weight:600;white-space:nowrap}
.um-tema__acciones{display:flex;gap:.35rem}
.um-tema__accion{width:32px;height:32px;border-radius:7px;border:1px solid #e4ede9;background:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#888;padding:0;transition:all .12s}
.um-tema__accion:hover{background:#def1ec;border-color:#b3e8da;color:#000}
.um-tema__accion--peligro:hover{background:#fdf0f0;border-color:#f5c6c6;color:#c33}
.um-tema__cuerpo{display:grid;grid-template-columns:1fr 1fr}
.um-tema__zona{display:flex;flex-direction:column;border-right:1px solid #f0f4f2}
.um-tema__zona:last-child{border-right:none}
.um-tema__zona-cab{display:flex;align-items:center;gap:.6rem;padding:.8rem 1.1rem;border-bottom:1px solid #f2f6f4;background:#fafcfb}
.um-tema__zona-icono{width:28px;height:28px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:.75rem}
.um-tema__zona-icono--video{background:#e6f4ee;color:#2e7d55}.um-tema__zona-icono--doc{background:#e6edf5;color:#3a5a8a}
.um-tema__zona-label{font-size:.78rem;font-weight:700}
.um-tema__zona-cuerpo{padding:.85rem 1.1rem;display:flex;flex-direction:column;gap:.5rem}
.um-tema__subida{display:flex;gap:.5rem;align-items:center;background:#f2f8f5;border:1.5px dashed #c4d9d2;border-radius:8px;padding:.55rem .75rem}
.um-tema__subida input{flex:1;font-size:.76rem;min-width:0;color:#666}
.um-tema__subir{padding:.28rem .7rem;border:1.5px solid #b3e8da;border-radius:8px;background:#b3e8da;font:600 .74rem 'DM Sans', system-ui, sans-serif;cursor:pointer;white-space:nowrap}
.um-tema__progreso{display:flex;align-items:center;gap:.5rem}
.um-tema__progreso[hidden]{display:none}
.um-tema__barra{flex:1;height:6px;background:#e8eeec;border-radius:3px;overflow:hidden}
.um-tema__relleno{width:0;height:100%;background:#3aaa74;border-radius:3px;transition:width .15s ease}
.um-tema__pct{font-size:.72rem;color:#667;min-width:2.5rem;text-align:right;font-variant-numeric:tabular-nums}
.um-tema__reusar{align-self:flex-start;background:none;border:0;padding:.2rem 0;font:600 .74rem 'DM Sans', system-ui, sans-serif;color:#3aaa74;text-decoration:underline;cursor:pointer}
.um-tema__mat{display:flex;align-items:center;gap:.5rem;padding:.4rem .6rem;background:#f7faf9;border:1px solid #e8eeec;border-radius:7px;font-size:.78rem}
.um-tema__mat-nombre{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#000;text-decoration:none;font-weight:600}
.um-tema__mat-tam{font-size:.68rem;color:#bbb}
.um-tema__mat-del{width:22px;height:22px;border-radius:5px;border:1px solid #f5c6c6;background:#fff;color:#c33;font-size:.65rem;cursor:pointer;padding:0}
@media (max-width:768px){.um-tema__cuerpo{grid-template-columns:1fr}.um-tema__zona{border-right:none;border-bottom:1px solid #f0f4f2}.um-tema__accion{width:44px;height:44px}}

