document.querySelectorAll('[data-um-temas]').forEach(function (lista) {
  var arrastrada = null, ind = document.createElement('div'); ind.className = 'um-temas__indicador';
  lista.addEventListener('dragstart', function (e) { arrastrada = e.target.closest('.um-tema'); arrastrada.classList.add('is-arrastrando'); });
  lista.addEventListener('dragend', function () { arrastrada.classList.remove('is-arrastrando'); ind.remove(); arrastrada = null; lista.querySelectorAll('.um-tema__num').forEach(function (n, i) { n.textContent = String(i + 1).padStart(2, '0'); }); });
  lista.addEventListener('dragover', function (e) {
    e.preventDefault(); var otra = e.target.closest('.um-tema'); if (!otra || otra === arrastrada) return;
    var r = otra.getBoundingClientRect(), antes = e.clientY < r.top + r.height / 2;
    lista.insertBefore(ind, antes ? otra : otra.nextSibling);
  });
  lista.addEventListener('drop', function (e) { e.preventDefault(); if (ind.parentNode) lista.insertBefore(arrastrada, ind); });
  lista.querySelectorAll('[data-subir]').forEach(function (b) {
    b.addEventListener('click', function () {
      var zona = b.closest('.um-tema__zona-cuerpo'), p = zona.querySelector('.um-tema__progreso'), rel = p.querySelector('.um-tema__relleno'), txt = p.querySelector('.um-tema__pct'), v = 0;
      p.hidden = false; var t = setInterval(function () { v = Math.min(100, v + 7); rel.style.width = v + '%'; txt.textContent = v + '%'; if (v === 100) clearInterval(t); }, 150);
    });
  });
});

piezas.css:
.um-bloque-form{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box}
.um-bloque-form__bloque{background:#fff;border:1px solid #e4ede9;border-radius:14px;padding:1.5rem 1.75rem;box-shadow:0 2px 12px rgba(0,0,0,.05);margin-bottom:1.15rem}
.um-bloque-form__bloque--completado{border-color:#b6e0cc;background:#f6fcf9}
.um-bloque-form__cab{display:flex;align-items:flex-start;gap:.8rem;margin-bottom:1.25rem;padding-bottom:.9rem;border-bottom:1px solid #f0f4f2}
.um-bloque-form__icono{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.um-bloque-form__icono svg{width:18px;height:18px}
.um-bloque-form__icono--info{background:#e6f4ee;color:#1f5d3d}.um-bloque-form__icono--media{background:#fff3e0;color:#8a4a00}.um-bloque-form__icono--org{background:#eef0fb;color:#2e3a7a}.um-bloque-form__icono--contenido{background:#fde8f0;color:#7a2660}
.um-bloque-form__titulo h3{font-size:.95rem;font-weight:700;margin:0}
.um-bloque-form__titulo p{font-size:.76rem;color:#555;margin:.15rem 0 0;line-height:1.45}
.um-bloque-form__grupo{display:flex;flex-direction:column;gap:.4rem;margin-bottom:1.35rem}
.um-bloque-form__grupo:last-child{margin-bottom:0}
.um-bloque-form__label{font-size:.8rem;font-weight:700;letter-spacing:.01em}
.um-bloque-form__input{width:100%;box-sizing:border-box;padding:.7rem 1rem;border:1.5px solid #e4ede9;border-radius:9px;font:.87rem 'DM Sans', system-ui, sans-serif;outline:none;background:#f9fbfa;transition:border-color .15s,background .15s,box-shadow .15s}
.um-bloque-form__input:focus{border-color:#b3e8da;background:#fff;box-shadow:0 0 0 3px rgba(111,181,155,.15)}
.um-bloque-form__input::placeholder{color:#bbb}
.um-bloque-form__acciones{display:flex;gap:.6rem;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:.9rem .25rem .25rem}
.um-bloque-form__acciones > div{display:flex;gap:.55rem;flex-wrap:wrap}
.um-bloque-form-btn{display:inline-flex;align-items:center;gap:.4rem;padding:.45rem 1rem;border:1.5px solid #e4ede9;border-radius:8px;background:#fff;font-family:inherit;font-size:.78rem;font-weight:600;color:#000;cursor:pointer;text-decoration:none;white-space:nowrap;transition:background .12s,border-color .12s,box-shadow .12s}
.um-bloque-form-btn svg{width:13px;height:13px;flex-shrink:0}
.um-bloque-form-btn:hover{background:#f4faf8;border-color:#b3e8da;box-shadow:0 2px 8px rgba(0,0,0,.06)}
.um-bloque-form-btn--primario{background:#b3e8da;border-color:#b3e8da;color:#1a2e28;box-shadow:0 2px 8px rgba(111,181,155,.35)}
.um-bloque-form-btn--primario:hover{opacity:.9;background:#b3e8da;box-shadow:0 4px 14px rgba(111,181,155,.45)}
.um-bloque-form-btn--sutil{border-color:transparent;background:transparent;color:#555;box-shadow:none}
.um-bloque-form-btn--sutil:hover{background:#f4faf8;color:#000;border-color:transparent;box-shadow:none}
.um-bloque-form-btn--peligro{border-color:#f3caca;background:#fff;color:#c33;box-shadow:none}
.um-bloque-form-btn--peligro:hover{background:#fdf0f0;border-color:#e99;color:#a22;box-shadow:0 2px 8px rgba(195,51,51,.1)}
.um-bloque-form-btn:disabled{opacity:.55;cursor:not-allowed}
@media (max-width:768px){.um-bloque-form-btn{min-height:44px}}

.um-botones{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box;display:flex;gap:.6rem;flex-wrap:wrap}
.um-botones-btn{display:inline-flex;align-items:center;gap:.4rem;padding:.45rem 1rem;border:1.5px solid #e4ede9;border-radius:8px;background:#fff;font-family:inherit;font-size:.78rem;font-weight:600;color:#000;cursor:pointer;text-decoration:none;white-space:nowrap;transition:background .12s,border-color .12s,box-shadow .12s}
.um-botones-btn svg{width:13px;height:13px;flex-shrink:0}
.um-botones-btn:hover{background:#f4faf8;border-color:#b3e8da;box-shadow:0 2px 8px rgba(0,0,0,.06)}
.um-botones-btn--primario{background:#b3e8da;border-color:#b3e8da;color:#1a2e28;box-shadow:0 2px 8px rgba(111,181,155,.35)}
.um-botones-btn--primario:hover{opacity:.9;background:#b3e8da;box-shadow:0 4px 14px rgba(111,181,155,.45)}
.um-botones-btn--sutil{border-color:transparent;background:transparent;color:#555;box-shadow:none}
.um-botones-btn--sutil:hover{background:#f4faf8;color:#000;border-color:transparent;box-shadow:none}
.um-botones-btn--peligro{border-color:#f3caca;background:#fff;color:#c33;box-shadow:none}
.um-botones-btn--peligro:hover{background:#fdf0f0;border-color:#e99;color:#a22;box-shadow:0 2px 8px rgba(195,51,51,.1)}
.um-botones-btn:disabled{opacity:.55;cursor:not-allowed}
@media (max-width:768px){.um-botones-btn{min-height:44px}}

.um-botones-btn[data-cargando='1']{cursor:wait;opacity:.85;pointer-events:none}
.um-botones__spinner{display:inline-block;width:1em;height:1em;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:um-botones-giro .75s linear infinite}
.um-botones__envoltorio{display:flex;align-items:center;justify-content:center;gap:.6em;line-height:1;width:100%}
@keyframes um-botones-giro{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.um-botones__spinner{animation-duration:1.6s}}

piezas.js:
document.querySelectorAll('[data-um-guardar]').forEach(function (b) {
  b.addEventListener('click', function () {
    var antes = b.innerHTML; b.dataset.cargando = '1';
    b.innerHTML = '<span class="um-botones__envoltorio"><span class="um-botones__spinner" aria-hidden="true"></span>Guardando…</span>';
    setTimeout(function () { b.innerHTML = antes; delete b.dataset.cargando; }, 1500);
  });
});

piezas.css:
.um-barras-dia{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box;padding:0;background:#fff;border:1px solid #e4ede9;border-radius:14px;box-shadow:0 2px 12px rgba(0,0,0,.05)}
.um-barras-dia__cab{display:flex;align-items:center;justify-content:space-between;padding:1.1rem 1.5rem;border-bottom:1px solid #f0f5f2}
.um-barras-dia__titulo{font-size:.9rem;font-weight:700}
.um-barras-dia__leyenda{font-size:.75rem;color:#888;display:inline-flex;align-items:center;gap:.35rem}
.um-barras-dia__leyenda i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-left:.4rem}
.um-barras-dia__l-vis{background:#b3e8da}.um-barras-dia__l-per{background:#3ba776}
.um-barras-dia__grafico{display:flex;align-items:flex-end;gap:3px;height:210px;padding:2.8rem 1.5rem .4rem}
.um-barras-dia__dia{flex:1 1 0;height:100%;position:relative;display:flex;align-items:flex-end;justify-content:center;min-width:4px}
.um-barras-dia__vis{width:100%;background:#b3e8da;border-radius:4px 4px 0 0;min-height:2px}
.um-barras-dia__per{position:absolute;bottom:0;width:45%;background:#3ba776;border-radius:3px 3px 0 0}
.um-barras-dia__dia:hover .um-barras-dia__vis{background:#8fd9c6}
.um-barras-dia__tip{position:absolute;top:-2.5rem;left:50%;transform:translateX(-50%);z-index:2;background:#2f3b37;color:#fff;font-size:.72rem;line-height:1.3;white-space:nowrap;padding:.3rem .55rem;border-radius:6px;pointer-events:none;opacity:0;transition:opacity .1s}
.um-barras-dia__tip b{display:block;font-weight:700}
.um-barras-dia__tip--izq{left:0;transform:none}.um-barras-dia__tip--der{left:auto;right:0;transform:none}
.um-barras-dia__dia:hover .um-barras-dia__tip{opacity:1}
.um-barras-dia__ejes{display:flex;justify-content:space-between;padding:0 1.5rem 1rem;font-size:.72rem;color:#aaa}

.um-modulos{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box;display:flex;flex-direction:column;gap:.6rem}
.um-modulos__item{display:flex;align-items:center;gap:.9rem;padding:.9rem 1.1rem;border:1.5px solid #e4ede9;border-radius:10px;background:#fff;cursor:pointer;user-select:none;transition:border-color .15s,background .15s,box-shadow .15s}
.um-modulos__item:hover{border-color:#b3e8da;background:#f4faf8;box-shadow:0 2px 8px rgba(0,0,0,.06)}
.um-modulos__item.asignado{border-color:#b3e8da;background:#def1ec;box-shadow:0 2px 8px rgba(111,181,155,.2)}
.um-modulos__check{width:20px;height:20px;border:2px solid #d8e8e2;border-radius:5px;background:#fff;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .12s,border-color .12s}
.um-modulos__item.asignado .um-modulos__check{background:#b3e8da;border-color:#b3e8da}
.um-modulos__check svg{width:12px;height:12px;opacity:0}
.um-modulos__item.asignado .um-modulos__check svg{opacity:1}
.um-modulos__acento{width:4px;height:38px;border-radius:4px;flex-shrink:0}
.um-modulos__info{flex:1;min-width:0;display:flex;flex-direction:column}
.um-modulos__titulo{font-size:.84rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.um-modulos__meta{font-size:.73rem;color:#555;margin-top:.15rem}

.re-cabecera{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec;padding:1.5rem;box-sizing:border-box;-webkit-font-smoothing:antialiased;display:flex;align-items:flex-end;gap:1.2rem;padding:2.6rem 2.6rem 1.2rem}
.re-cabecera p{margin:0}
.re-cabecera__titulos{flex:1;min-width:0}
.re-cabecera__antetitulo{margin-bottom:.3rem!important;color:#15161a;font:600 .85rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-cabecera__titulo{margin:0;font:800 2.5rem/1.05 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.04em;color:#15161a}
.re-cabecera__titulo em{font:inherit;font-style:normal;padding:0 .06em;background:linear-gradient(transparent 58%,#d6e022 58%,#d6e022 92%,transparent 92%)}
.re-cabecera__sub{margin-top:.4rem!important;color:#6b6b60;font-size:1rem}
.re-cabecera__acciones{display:flex;flex-wrap:wrap;gap:.5rem}
.re-cabecera__menu{display:none;align-self:flex-start;padding:.55rem 1rem;border:1px solid rgba(21,22,26,.09);border-radius:999px;background:#fff;font:500 .8rem 'Inter Variable', 'Inter', system-ui, sans-serif;cursor:pointer}
@media (max-width:900px){.re-cabecera{flex-wrap:wrap;padding:1.2rem 1rem}.re-cabecera__menu{display:block}.re-cabecera__acciones{width:100%}.re-cabecera__titulo{font-size:1.9rem}}
.re-cabecera-btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.62rem 1.2rem;border:0;border-radius:980px;background:#15161a;color:#fff;font:500 .9rem/1.2 'Inter Variable', 'Inter', system-ui, sans-serif;text-decoration:none;white-space:nowrap;cursor:pointer;transition:background .25s}
.re-cabecera-btn--ghost{background:#fff;color:#15161a;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18)}
.re-cabecera-btn--ghost:hover{box-shadow:inset 0 0 0 1px #15161a}
.re-cabecera-btn--sm{padding:.42rem .9rem;font-size:.82rem}
.re-cabecera-btn--danger{background:#fdeceb;color:#d70015}
.re-cabecera-btn--danger:hover{background:#d70015;color:#fff}

.re-viendo{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.6rem 1rem;padding:.6rem 2.6rem;background:#15161a;color:#fff;font:400 .88rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-viendo strong{color:#d6e022}
.re-viendo__volver{padding:0;border:0;background:none;color:#fff;font:inherit;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
@media (max-width:900px){.re-viendo{padding:.6rem 1rem}}

.re-estados{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec;padding:1.5rem;box-sizing:border-box;-webkit-font-smoothing:antialiased;display:flex;flex-wrap:wrap;gap:.5rem}
.re-estados-status{display:inline-flex;align-items:center;padding:.15rem .6rem;border-radius:980px;background:var(--st-bg,#ecebe2);color:var(--st-ink,#6b6b60);font:500 .78rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif;white-space:nowrap}
.re-estados-status[data-status='solicitud'],.re-estados-status[data-status='pendiente_pago']{--st-bg:#f6f8ce;--st-ink:#8a5700}
.re-estados-status[data-status='confirmada']{--st-bg:#f1f4c4;--st-ink:#15161a}
.re-estados-status[data-status='en_curso']{--st-bg:#d7ecdf;--st-ink:#1f7a4d}
.re-estados-status[data-status='cancelada'],.re-estados-status[data-status='rechazada'],.re-estados-status[data-status='no_show']{--st-bg:#f6e0dc;--st-ink:#c62f2f}

.re-cal{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;padding:1.6rem 1.8rem 1.4rem;border:1px solid rgba(21,22,26,.09);border-radius:20px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12)}
.re-cal *{box-sizing:border-box}
.re-cal [data-status]{--bar:#dfe6ee;--bar-ink:#15161a}
.re-cal [data-status='confirmada']{--bar:#15161a;--bar-ink:#fff}
.re-cal [data-status='en_curso']{--bar:#1f7a4d;--bar-ink:#fff}
.re-cal [data-status='finalizada']{--bar:#9aa6b8;--bar-ink:#fff}
.re-cal [data-status='solicitud'],.re-cal [data-status='pendiente_pago']{--bar:#ffcf66;--bar-ink:#4d3200}
.re-cal [data-status='bloqueo']{--bar:repeating-linear-gradient(-45deg,#c9d3df 0 6px,#dde4ec 6px 12px);--bar-ink:#15161a}
.re-cal__cab{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1.4rem}
.re-cal__mes{margin:0;font:800 2.4rem/1 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.03em}
.re-cal__ocup{margin:.45rem 0 0;color:#6b6b60;font-size:.92rem}
.re-cal__nav{display:flex;align-items:center;gap:.5rem}
.re-cal__flecha,.re-cal__hoy{display:grid;place-items:center;min-width:42px;height:42px;padding:0 .9rem;border-radius:999px;background:#fff;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18);color:#15161a;font-weight:500;text-decoration:none}
.re-cal__flecha{padding:0;font-size:1.1rem}
.re-cal__flecha:hover,.re-cal__hoy:hover{background:#15161a;color:#fff;box-shadow:none}
.re-cal__hoy[aria-current='true']{background:#ecebe2}
