document.querySelectorAll('[data-re-chat]').forEach(function (c) {
  var lista = c.querySelector('.re-chat__lista'), t = c.querySelector('textarea');
  lista.scrollTop = lista.scrollHeight;
  function enviar() { if (!t.value.trim()) return; var li = document.createElement('li'); li.className = 're-chat__msg re-chat__msg--mia'; var p = document.createElement('p'); p.className = 're-chat__burbuja'; p.textContent = t.value; var s = document.createElement('small'); s.className = 're-chat__meta'; s.textContent = 'Tú · ahora'; li.append(p, s); lista.appendChild(li); t.value = ''; t.style.height = 'auto'; lista.scrollTop = lista.scrollHeight; }
  t.addEventListener('keydown', function (e) { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); enviar(); } });
  t.addEventListener('input', function () { t.style.height = 'auto'; t.style.height = Math.min(t.scrollHeight, 160) + 'px'; });
  c.querySelector('form').addEventListener('submit', enviar);
});

