document.querySelectorAll('[data-re-direccion]').forEach(function (b) {
  var nombre = b.querySelector('#re-dir-nombre'), slug = b.querySelector('.re-direccion__input'), tocado = !!slug.value;
  function aSlug(t) { return t.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60); }
  nombre.addEventListener('input', function () { if (!tocado) slug.value = aSlug(nombre.value); });
  slug.addEventListener('input', function () { tocado = slug.value !== ''; });
  slug.addEventListener('blur', function () { slug.value = aSlug(slug.value); });
});

