.re-tabla-movil-btn--danger{background:#fdeceb;color:#d70015}
.re-tabla-movil-btn--danger:hover{background:#d70015;color:#fff}

.re-acceso{display:grid;grid-template-columns:1.1fr 1fr;min-height:560px;font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec}
.re-acceso *{box-sizing:border-box}
.re-acceso p{margin:0}
.re-acceso__marca{position:relative;display:flex;flex-direction:column;justify-content:flex-end;gap:1.2rem;overflow:hidden;padding:clamp(2rem,5vw,4.5rem);background:#15161a;color:#f5f4ec}
.re-acceso__marca::before{content:'';position:absolute;inset:0;background-image:radial-gradient(rgba(245,244,236,.09) 1px,transparent 1px);background-size:26px 26px}
.re-acceso__brillo{position:absolute;top:-180px;left:-140px;width:520px;height:520px;border-radius:50%;background:#d6e022;filter:blur(120px);opacity:.28}
.re-acceso__marca p{position:relative}
.re-acceso__ante{font:700 .8rem/1 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:.08em;text-transform:uppercase;color:#d6e022}
.re-acceso__lema{font:900 clamp(2.4rem,4.6vw,4.2rem)/.98 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.045em}
.re-acceso__lema span{background:#d6e022;color:#15161a;padding:0 .12em;border-radius:.12em}
.re-acceso__mano{font:400 1.9rem/1.1 'Just Another Hand',cursive;color:rgba(245,244,236,.75);transform:rotate(-2deg);transform-origin:left}
.re-acceso__lado{display:flex;flex-direction:column;justify-content:center;gap:1.8rem;width:100%;max-width:400px;margin:0 auto;padding:3rem 1.5rem}
.re-acceso__logo{font:800 1.5rem/1 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.04em}
.re-acceso__logo small{display:block;margin-top:.3rem;font:400 .75rem/1 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:0;color:#6b6b60}
.re-acceso__titulo{margin:0;font:800 1.6rem/1.05 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.035em}
.re-acceso__titulo em{font-style:normal;padding:0 .06em;background:linear-gradient(transparent 58%,#d6e022 58%,#d6e022 92%,transparent 92%)}
.re-acceso__form{display:flex;flex-direction:column;gap:1.3rem}
.re-acceso__campo{display:flex;flex-direction:column;gap:.4rem}
.re-acceso__campo label{color:#6b6b60;font:500 .82rem/1.5 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-acceso__campo input{min-height:44px;padding:.65rem .85rem;border:1px solid #d2d2d7;border-radius:10px;background:#fff;font:400 .95rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-acceso__campo input:focus{border-color:#15161a;box-shadow:0 0 0 4px rgba(0,113,227,.18);outline:none}
.re-acceso__boton{padding:.75rem 1.2rem;border:0;border-radius:980px;background:#15161a;color:#fff;font:500 .95rem/1.2 'Inter Variable', 'Inter', system-ui, sans-serif;cursor:pointer}
@media (max-width:800px){.re-acceso{grid-template-columns:1fr}.re-acceso__marca{min-height:34vh}}

.re-estancias{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec;padding:1.5rem;box-sizing:border-box;-webkit-font-smoothing:antialiased;background:#fff;border:1px solid rgba(21,22,26,.09);border-radius:18px;box-shadow:0 1px 2px rgba(21,22,26,.04),0 18px 40px -28px rgba(21,22,26,.35);padding:1.6rem 1.8rem}
.re-estancias__sub{margin:1.2rem 0 .3rem;font:600 .95rem/1.3 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-estancias__sub:first-child{margin-top:0}
.re-estancias__lista{margin:0;padding:0;list-style:none}
.re-estancias__lista li + li{border-top:1px solid rgba(21,22,26,.09)}
.re-estancias__lista a{display:grid;grid-template-columns:1fr auto;gap:.1rem 1rem;padding:.65rem 0;color:inherit;text-decoration:none}
.re-estancias__lista a:hover .re-estancias__apt{text-decoration:underline}
.re-estancias__apt{font-weight:600}
.re-estancias__quien,.re-estancias__fechas{grid-column:1;font-size:.88rem}
.re-estancias__fechas,.re-estancias__vacio{color:#6b6b60}
.re-estancias__vacio{margin:0;font-size:.93rem}
.re-estancias-status{grid-column:2;grid-row:1;align-self:start}
.re-estancias-status{display:inline-flex;align-items:center;padding:.15rem .6rem;border-radius:980px;background:var(--st-bg,#ecebe2);color:var(--st-ink,#6b6b60);font:500 .78rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif;white-space:nowrap}
.re-estancias-status[data-status='solicitud'],.re-estancias-status[data-status='pendiente_pago']{--st-bg:#f6f8ce;--st-ink:#8a5700}
.re-estancias-status[data-status='confirmada']{--st-bg:#f1f4c4;--st-ink:#15161a}
.re-estancias-status[data-status='en_curso']{--st-bg:#d7ecdf;--st-ink:#1f7a4d}
.re-estancias-status[data-status='cancelada'],.re-estancias-status[data-status='rechazada'],.re-estancias-status[data-status='no_show']{--st-bg:#f6e0dc;--st-ink:#c62f2f}
